WITH valid AS (SELECT id, order_id, method, amount, paid_at, status, TRIM(method) AS clean_method, COALESCE(method, 'DIRECT') AS method_filled FROM payments WHERE paid_at >= TO_TIMESTAMP('2023-05-26 18:00:00') AND order_id IS NOT NULL), scored AS (SELECT id, order_id, paid_at, status, method_filled, LAG(amount, 1) OVER (ORDER BY paid_at, id) AS prev_amount, RANK() OVER (PARTITION BY order_id ORDER BY amount DESC) AS amount_rank FROM valid), metrics AS (SELECT id, order_id, paid_at, status, prev_amount, amount_rank, AVG(prev_amount) OVER w_recent AS last4_avg_prev_amount, COUNT(prev_amount) OVER w_recent AS last4_count_prev_amount, MIN(prev_amount) OVER w_recent AS last4_min_prev_amount FROM scored WHERE prev_amount >= 1580 WINDOW w_recent AS (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW)), joined AS (SELECT src.*, p.order_date FROM metrics src LEFT JOIN orders p ON src.order_id = p.id) SELECT id, order_id, metric_name, value FROM (SELECT id, order_id, prev_amount, last4_min_prev_amount, last4_avg_prev_amount FROM joined) src UNPIVOT (value FOR metric_name IN (prev_amount, last4_min_prev_amount, last4_avg_prev_amount))
